const REGION_COLOR = { "Jérikko": "#E85D4A", "Ingíui": "#F0A050", "Nãi": "#F0D060", "Tángo": "#5FBF7A", "Tígua": "#5B9FE8", "Astã": "#7C6FE0", "Amaskás": "#B07CE8", "Mount Ịsa": "#F5F3EE", "Kuàña": "#8A8578" };
